\begin{itemchoice}
			\itemch Ta có $f(x)=4\sin x\cos x+2x=2\sin 2x+2x$. Suy ra $f'(x)=4\cos 2x+2$.
			\itemch Ta có $f'(x)=0\Leftrightarrow \cos 2x=-\frac{1}{2}\Leftrightarrow\left[ \begin{array}{l}
2x=\frac{2\pi}{3}+k2\pi\\2x=-\frac{2\pi}{3}+k2\pi
\end{array} \right.\Leftrightarrow\left[ \begin{array}{l}
x=\frac{\pi}{3}+k\pi \\x=-\frac{\pi}{3}+k\pi
\end{array} \right.\quad(k \in \mathbb{Z}).$\\
			Tìm các nghiệm thuộc $[-\pi ;\pi]$.
			\begin{itemize}
				\item $-\pi\leq\frac{\pi}{3}+k\pi\leq\pi\Leftrightarrow-\dfrac{4}{3}\leq k \leq \dfrac{2}{3}$, suy ra $k=-1$, $k=0$.\\
				Có hai nghiệm thỏa mãn là $x=\dfrac{\pi}{3}$ và $x=-\dfrac{2\pi}{3}$
				\item $-\pi\leq-\frac{\pi}{3}+k\pi\leq\pi\Leftrightarrow-\dfrac{2}{3}\leq k \leq \dfrac{4}{3}$, suy ra $k=0$, $k=1$.\\
				Có hai nghiệm thỏa mãn là $x=-\dfrac{\pi}{3}$ và $x=\dfrac{2\pi}{3}$
			\end{itemize}
			Bảng xét dấu 
			\begin{center}
				<img src='HinhAnh/sol_b5d67dacde_lg_tikz_1.png' style='max-width: 100%; height: auto; display: block; margin: 10px auto;' />
			\end{center}
			Dựa vào bảng xét dấu $f’(x)$, hàm số đã cho có $4$ điểm cực trị.
			\itemch Ta có $-\dfrac{\pi}{3}\in(-2;-1)$, suy ra hàm số không đồng biến trên $(-2;-1)$.
			\itemch Trên $\left[0;\dfrac{\pi}{2}\right]$, $f'(x)=0\Leftrightarrow x=\frac{\pi}{3}$.\\
			Ta có $f(0)=0$, $f\left(\dfrac{\pi}{3}\right)=\dfrac{2\pi}{3}+\sqrt{3}$, $f\left(\dfrac{\pi}{2}\right)=\pi$.\\
			Suy ra, giá trị lớn nhất của $f(x)$ trên đoạn $\left[0;\dfrac{\pi}{2}\right]$ là $\dfrac{2\pi}{3}+\sqrt{3}$.
		\end{itemchoice}
